import sqlite3
import os
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Log the search action
    db = get_db()
    log_query = f"INSERT INTO audit_log (action, details) VALUES ('search', 'field={field}, value={value}')"
    db.execute(log_query)
    db.commit()

    # Perform the actual search with parameterized query
    search_query = f"SELECT username, email, role FROM users WHERE {field} LIKE ?"
    results = db.execute(search_query, (f'%{value}%',)).fetchall()

    return jsonify([dict(row) for row in results])

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    user = db.execute('SELECT username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    api_key = hashlib.sha256(os.urandom(32)).hexdigest()
    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, api_key) VALUES (?, ?, ?)',
            (data['username'], data['email'], api_key)
        )
        db.commit()
        return jsonify({'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/admin/export', methods=['GET'])
def export_users():
    """Export user data. Requires admin API key."""
    api_key = request.headers.get('X-API-Key', '')
    db = get_db()
    admin = db.execute(
        'SELECT * FROM users WHERE api_key = ? AND role = ?',
        (api_key, 'admin')
    ).fetchone()
    if not admin:
        return jsonify({'error': 'Unauthorized'}), 403

    users = db.execute('SELECT id, username, email, role FROM users').fetchall()
    return jsonify([dict(row) for row in users])

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
